import{_ as t,o as a,c as n,ag as o}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"New Tenant Setup","description":"","frontmatter":{},"headers":[],"relativePath":"new-tenant-setup.md","filePath":"new-tenant-setup.md"}'),s={name:"new-tenant-setup.md"};function r(i,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="new-tenant-setup" tabindex="-1">New Tenant Setup <a class="header-anchor" href="#new-tenant-setup" aria-label="Permalink to &quot;New Tenant Setup&quot;">​</a></h1><p>Seven steps. No new Slack app, no Google Cloud, no Sheets, no Railway, no scripts, no restart.</p><p>VERA runs as a <strong>single distributed Slack app</strong> that each client workspace installs into their own Slack. You do not create a new Slack app per tenant. The shared Client ID, Client Secret, and App Token are the same for every tenant — only the workspace bot token (<code>xoxb-…</code>) differs, and that is generated automatically when the client workspace clicks <strong>Allow</strong> during install.</p><hr><h2 id="_1-install-vera-into-the-client-s-slack-workspace" tabindex="-1">1. Install VERA into the client&#39;s Slack workspace <a class="header-anchor" href="#_1-install-vera-into-the-client-s-slack-workspace" aria-label="Permalink to &quot;1. Install VERA into the client&#39;s Slack workspace&quot;">​</a></h2><p>Open <code>&lt;base-url&gt;/slack/install</code> in a browser (the same domain that hosts <code>/admin</code>).</p><p>Fill the form. Use the values from any existing tenant row in <code>/admin</code> for the three Slack fields — they&#39;re shared across all tenants.</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Client ID</td><td>Copy from any existing tenant row in <code>/admin</code></td></tr><tr><td>Client Secret</td><td>Copy from any existing tenant row in <code>/admin</code></td></tr><tr><td>App Token</td><td>Copy from any existing tenant row in <code>/admin</code> (<code>xapp-…</code>)</td></tr><tr><td>Timezone</td><td>The client&#39;s timezone</td></tr><tr><td>Google Sheet ID</td><td><strong>Leave blank</strong> (Postgres-native)</td></tr><tr><td>Google Credentials JSON</td><td><strong>Leave blank</strong> (Postgres-native)</td></tr></tbody></table><p>Click <strong>Install to Slack</strong>. You&#39;ll be redirected to Slack&#39;s authorization page.</p><p>On the Slack page:</p><ul><li>Make sure the client&#39;s workspace is selected in the top-right dropdown</li><li>Click <strong>Allow</strong></li></ul><p>VERA receives the workspace&#39;s bot token, creates the tenant in Postgres, and shows a success page.</p><p><strong>What success looks like:</strong> the page reads &quot;VERA installed for [Workspace Name]&quot;. The tenant now appears in <code>/admin</code> with its Slack tokens already filled in.</p><hr><h2 id="_2-create-the-audit-channel-and-invite-the-bot" tabindex="-1">2. Create the audit channel and invite the bot <a class="header-anchor" href="#_2-create-the-audit-channel-and-invite-the-bot" aria-label="Permalink to &quot;2. Create the audit channel and invite the bot&quot;">​</a></h2><p>In the client&#39;s Slack workspace:</p><ul><li>Create a channel (e.g. <code>#vera-audit</code>) — private is fine</li><li>Copy the channel ID: click the channel name → <strong>About</strong> → copy the ID starting with <code>C</code></li><li>Type <code>/invite @VERA</code> in the channel</li></ul><p><strong>What success looks like:</strong> the bot appears in the channel member list.</p><blockquote><p>The channel ID starts with <code>C</code>, not the channel name. Using the name will fail silently.</p></blockquote><hr><h2 id="_3-set-the-audit-channel-id-in-admin" tabindex="-1">3. Set the audit channel ID in /admin <a class="header-anchor" href="#_3-set-the-audit-channel-id-in-admin" aria-label="Permalink to &quot;3. Set the audit channel ID in /admin&quot;">​</a></h2><p>Back in <code>/admin</code>, find the new tenant row (it&#39;s already there — created automatically by the install in step 1).</p><ul><li>Paste the <code>C…</code> ID into the <strong>Audit Channel</strong> field</li><li>Click <strong>Verify</strong> next to that field — wait for the green confirmation that the bot is in the channel</li><li>While you&#39;re in the row, set <strong>HQ Location</strong> (e.g. <code>Ann Arbor, MI</code>) — the client&#39;s headquarters metro area. It rarely changes and feeds salary benchmark data later; there&#39;s no rush, but it&#39;s convenient to set alongside the other fields now</li><li>Click <strong>Save</strong></li></ul><p><strong>What success looks like:</strong> the audit channel is set, Verify is green.</p><hr><h2 id="_4-add-the-first-owner" tabindex="-1">4. Add the first owner <a class="header-anchor" href="#_4-add-the-first-owner" aria-label="Permalink to &quot;4. Add the first owner&quot;">​</a></h2><p>The database starts empty of people. The first owner must be added before the full smoke test will pass.</p><p>In <code>/admin</code>, find the new tenant row. In the <strong>Set Owner</strong> column:</p><ul><li>Paste the owner&#39;s Slack user ID into the input (e.g. <code>U0B0K62GCCV</code>)</li><li>Click <strong>Set Owner</strong></li></ul><p>The status shows ✅ Created [Name] as owner on success. If the user already exists in the system with a lower role, it is promoted to owner automatically.</p><p>To find a Slack user ID: click the person&#39;s profile in Slack → <strong>⋮</strong> → <strong>Copy member ID</strong>.</p><p><strong>What success looks like:</strong> the Set Owner cell shows a green confirmation. The owner can now DM VERA normally and all owner-level commands will work.</p><hr><h2 id="_5-seed-protected-projects" tabindex="-1">5. Seed protected projects <a class="header-anchor" href="#_5-seed-protected-projects" aria-label="Permalink to &quot;5. Seed protected projects&quot;">​</a></h2><p>The PTO, Sick, and Leave projects must exist before any team member can log time off. They are not created automatically — run this once via DM to VERA from the owner account:</p><blockquote><p>run setup protected projects</p></blockquote><p><strong>What success looks like:</strong> VERA confirms the three protected projects have been created. Time-off requests will now work for all users in the workspace.</p><hr><h2 id="_6-verify" tabindex="-1">6. Verify <a class="header-anchor" href="#_6-verify" aria-label="Permalink to &quot;6. Verify&quot;">​</a></h2><p>In <code>/admin</code>, click <strong>Verify</strong> on the new tenant row. Six checks run automatically:</p><table tabindex="0"><thead><tr><th>Check</th><th>What it proves</th></tr></thead><tbody><tr><td>Slack bot token</td><td>Token is valid and not revoked</td></tr><tr><td>Slack app token</td><td>Token is valid and not revoked</td></tr><tr><td>Bot DM round-trip</td><td>Bot can DM the owner and delete the message</td></tr><tr><td>Audit channel post</td><td>Bot can post to and delete from the audit channel</td></tr><tr><td>Postgres round-trip</td><td>Database is reachable and write/read/delete works</td></tr><tr><td>Dashboard query</td><td>Reporting SQL runs cleanly against this tenant&#39;s data</td></tr></tbody></table><p>All six must show green. Common failures:</p><ul><li><strong>Bot DM round-trip skips or fails</strong> — add the owner user first (step 4) and re-verify</li><li><strong>Audit channel fails</strong> — the bot was not invited to the channel. Run <code>/invite @VERA</code> (step 2) and re-verify</li><li><strong>Token fails</strong> — re-install via <code>/slack/install</code> (step 1)</li></ul><p><strong>What success looks like:</strong> six green checks. The tenant is fully operational.</p><hr><h2 id="_7-send-the-dashboard-url-to-the-client" tabindex="-1">7. Send the dashboard URL to the client <a class="header-anchor" href="#_7-send-the-dashboard-url-to-the-client" aria-label="Permalink to &quot;7. Send the dashboard URL to the client&quot;">​</a></h2><p>The dashboard URL was auto-generated when the tenant was created. It is visible in the <code>/admin</code> tenant row.</p><p>Format: <code>https://dash.getvera.site/d/&lt;slug&gt;</code></p><p>Open it in an incognito window first — it should render the project list (empty at this point, which is correct). Send the URL to the client.</p><p><strong>What success looks like:</strong> the client can open the URL without a login, sees their project list, and the page auto-refreshes every 60 seconds.</p><hr><h2 id="removing-a-tenant-that-was-added-as-a-separate-slack-app" tabindex="-1">Removing a tenant that was added as a separate Slack app <a class="header-anchor" href="#removing-a-tenant-that-was-added-as-a-separate-slack-app" aria-label="Permalink to &quot;Removing a tenant that was added as a separate Slack app&quot;">​</a></h2><p>If a tenant was created using the <strong>Create Slack app from manifest</strong> button in <code>/admin</code> — producing a brand-new Slack app per tenant instead of installing the shared distributed app — remove it as follows.</p><p><strong>Step 1 — Delete the tenant row in <code>/admin</code></strong></p><p>Find the tenant row and click <strong>Delete</strong>. This removes it from the tenants file immediately. VERA stops routing messages for that workspace.</p><blockquote><p>Deletion removes the entry from the tenants file only. Any Postgres rows for that tenant are not touched. For a tenant that never had real data (e.g. a mistaken onboarding) this is fine and no further DB action is needed.</p></blockquote><p><strong>Step 2 — Delete the rogue Slack app at api.slack.com/apps</strong></p><ul><li>Go to <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">api.slack.com/apps</a></li><li>Find the app that was created per-tenant (it will have a different App ID from the shared app <code>A0AE27UD6H3</code>)</li><li>Open it → <strong>Basic Information</strong> → scroll to the bottom → <strong>Delete App</strong></li><li>Confirm deletion</li></ul><p>This revokes all tokens associated with that app and removes it from the workspace&#39;s installed apps list.</p><p><strong>What success looks like:</strong> the tenant no longer appears in <code>/admin</code>, and the app no longer appears in the Slack workspace&#39;s installed apps or at <code>api.slack.com/apps</code>.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p><strong>The database starts empty of operational data.</strong> Structural prerequisites (disciplines, tasks, time-off projects, Internal client) are seeded automatically. The first real client interaction — logging a time entry, creating a project — is the first row in the database.</p><p><strong>One Slack app, many workspaces.</strong> VERA uses a single publicly-distributed Slack app (<code>A0AE27UD6H3</code>). Each client workspace installs that one app via OAuth. Do <strong>not</strong> create a new Slack app per tenant — the <code>/admin</code> &quot;Create Slack app from manifest&quot; button exists for the original one-time app creation only and should not be used during tenant onboarding.</p><p><strong>Google Sheets are not required.</strong> New tenants are always Postgres-native. If you want to set up a client-facing reporting sheet using <code>IMPORTRANGE</code>, that is a separate, optional step and does not affect VERA&#39;s operation.</p><p><strong>Legacy tenants (Sheets-first).</strong> If you are migrating an existing Sheets-based tenant to Postgres, that is a different process — see the <code>docs/postgres-migration.md</code> guide and the backfill script.</p>',66)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
